// Generates supabase/seed.sql from src/lib/catalog.ts (Node 24 strips TS types natively).
// Usage: npm run db:seed:gen
import { writeFileSync } from "node:fs";
import { LEAGUES, TEAMS } from "../src/lib/catalog.ts";

const q = (v) => (v === null || v === undefined ? "null" : `'${String(v).replaceAll("'", "''")}'`);

const lines = [
  "-- GENERATED by scripts/gen-seed.mjs from src/lib/catalog.ts — do not edit by hand.",
  "",
  "insert into public.leagues (id, name, name_zh) values",
  LEAGUES.map((l) => `  (${q(l.id)}, ${q(l.name)}, ${q(l.nameZh)})`).join(",\n"),
  "on conflict (id) do update set name = excluded.name, name_zh = excluded.name_zh;",
  "",
  "insert into public.teams (id, league_id, abbr, name, name_zh, city, venue_tz) values",
  TEAMS.map((t) => `  (${q(t.id)}, ${q(t.leagueId)}, ${q(t.abbr)}, ${q(t.name)}, ${q(t.nameZh)}, ${q(t.city)}, ${q(t.venueTz)})`).join(",\n"),
  "on conflict (id) do update set name = excluded.name, name_zh = excluded.name_zh, city = excluded.city, venue_tz = excluded.venue_tz;",
  "",
];

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log(`seed.sql: ${LEAGUES.length} leagues, ${TEAMS.length} teams`);
